@using Umbraco.Bench.Umbraco.Models
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlogFrontPage>
@{
    Layout = "layout.cshtml";
    var posts = Model.Children<BlogPost>()?.OrderByDescending(post => post.PublishDate).ToList() ?? [];
}
<h1 class="text-5xl font-extrabold tracking-tight text-slate-900">@Model.Title</h1>

@await Html.GetBlockGridHtmlAsync(Model, "blocks")

<section class="mt-16">
    <h2 class="mb-8 text-sm font-semibold uppercase tracking-widest text-indigo-600">Latest posts</h2>
    <div class="grid gap-10 sm:grid-cols-2">
        @foreach (var post in posts)
        {
            <article class="group overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200 transition hover:shadow-lg">
                <a href="@post.Url()" class="block">
                    @if (post.ListingImage is not null)
                    {
                        <img src="@post.ListingImage.GetCropUrl(width: 800, height: 450)" alt="@post.ListingImage.Name" loading="lazy" class="aspect-video w-full object-cover" />
                    }
                    <div class="p-6">
                        @if (post.PublishDate != default)
                        {
                            <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</time>
                        }
                        <h3 class="mt-2 text-2xl font-bold text-slate-900 group-hover:text-indigo-600">@(post.Title ?? post.Name)</h3>
                        @if (!string.IsNullOrWhiteSpace(post.Excerpt))
                        {
                            <p class="mt-3 text-slate-600">@post.Excerpt</p>
                        }
                        <span class="mt-4 inline-block font-semibold text-indigo-600">Read the post &rarr;</span>
                    </div>
                </a>
            </article>
        }
    </div>
</section>

