    <header class="mb-10">
        @if (Model.PublishDate != default)
        {
            <time datetime="@Model.PublishDate.ToString("yyyy-MM-dd")" class="text-sm font-semibold uppercase tracking-widest text-indigo-600">@Model.PublishDate.ToString("d MMMM yyyy")</time>
        }
        <h1 class="mt-3 text-5xl font-extrabold tracking-tight text-slate-900">@(Model.Title ?? Model.Name)</h1>
        @if (!string.IsNullOrWhiteSpace(Model.Excerpt))
        {
            <p class="mt-5 text-xl leading-relaxed text-slate-600">@Model.Excerpt</p>
        }
    </header>

    @if (Model.ListingImage is not null)
    {
        <img src="@Model.ListingImage.GetCropUrl(width: 1600, height: 800)" alt="@Model.ListingImage.Name" class="mb-10 aspect-[2/1] w-full rounded-2xl object-cover shadow-md" />
    }

    @await Html.GetBlockGridHtmlAsync(Model, "blocks")

    @if (frontPage is not null)
    {
        <a href="@frontPage.Url()" class="mt-12 inline-block font-semibold text-indigo-600 hover:underline">&larr; All posts</a>
    }
